"""Generate the web's rule descriptions from the backend's source of truth."""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
rules = json.loads((root / "backend/app/grading/subject_rules.json").read_text(encoding="utf-8"))
(root / "web/src/lib/gradingRules.ts").write_text(
    "// Generated by scripts/sync-grading-rules.py; edit backend/app/grading/subject_rules.json.\n"
    + "export const gradingRules: Record<string, string> = " + json.dumps(rules, ensure_ascii=False, indent=2) + "\n",
    encoding="utf-8",
)
